import unittest
from cfg.loader import load_config

class TestLoader(unittest.TestCase):
    def test_load_config(self):
        defaults = {
            "host": "localhost",
            "port": 80,
            "debug": False,
            "threshold": 0.5
        }
        env = {
            "APP_HOST": "example.com",
            "APP_PORT": "8080",
            "APP_DEBUG": "True",
            "APP_THRESHOLD": "0.75"
        }
        config = load_config(defaults, env)
        self.assertEqual(config["host"], "example.com")
        self.assertEqual(config["port"], 8080)
        self.assertEqual(config["debug"], True)
        self.assertEqual(config["threshold"], 0.75)

    def test_load_config_no_override(self):
        defaults = {
            "host": "localhost",
            "port": 80
        }
        env = {
            "OTHER_VAR": "some_value"
        }
        config = load_config(defaults, env)
        self.assertEqual(config["host"], "localhost")
        self.assertEqual(config["port"], 80)

    def test_load_config_partial_override(self):
        defaults = {
            "host": "localhost",
            "port": 80,
            "debug": False
        }
        env = {
            "APP_HOST": "example.com"
        }
        config = load_config(defaults, env)
        self.assertEqual(config["host"], "example.com")
        self.assertEqual(config["port"], 80)
        self.assertEqual(config["debug"], False)

    def test_load_config_case_insensitivity(self):
        defaults = {
            "host": "localhost",
            "port": 80
        }
        env = {
            "APP_HOST": "example.com",
            "APP_PORT": "8080"
        }
        config = load_config(defaults, env)
        self.assertEqual(config["host"], "example.com")
        self.assertEqual(config["port"], 8080)

if __name__ == '__main__':
    unittest.main()
